From Coq Require Import List String.
From Buri Require Import Wire Native.
Import ListNotations Native.Native.
Open Scope string_scope.
Definition io_read_text : string := "".
Definition io_read_nodes :=
 match Wire.decode_text io_read_text with
 | Some (Wire.Cons (Wire.Atom false "buri-constructor-native-1") (Wire.Cons tagged Wire.Nil)) =>
   match untag 500 tagged with Some root => elements root | _ => None end
 | _ => None end.
Definition io_read_decode := match io_read_nodes with
 | Some xs => definitions 500 (firstn 1 (skipn 0 xs)) | None => None end.
Definition io_read_program := Eval vm_compute in
 match io_read_decode with Some ds => ds | None => [] end.
Theorem io_read_exact : io_read_decode = Some io_read_program.
Proof. vm_compute. reflexivity. Qed.
Theorem io_read_names : map fst io_read_program = ["kl:read-file-as-string"].
Proof. vm_compute. reflexivity. Qed.
Global Opaque io_read_text io_read_nodes io_read_decode.
